import type { AbilityId } from '../../lib/formulas/abilities';

export type VagrantCategory = 'warrior' | 'spy' | 'remoteSupport' | 'magicWarrior';

export interface ChildhoodExperienceRow {
  /** d66 range as printed, e.g. "11-12"; a bare "1".."6" for the five D6 tables. */
  roll: string;
  /** Character Types barred from this result (reroll if you have one). Empty when the book prints no such restriction. */
  deprecatedTypes: string[];
  experience: string;
  /** Tag referenced by the separate Adolescent Experience tables, e.g. "Focus on Accuracy". Not every row has one. */
  focus: string | null;
  /** Ability Score Correction, keyed the same way `dice()` in `data/races.ts` keys the racial A-F dice. */
  correction: Record<AbilityId, number>;
}

export interface ChildhoodExperienceTable {
  raceId: string;
  category: VagrantCategory;
  /** Five tables in the book are a plain 1d6 roll instead of the usual 1d66. */
  diceType: 'd66' | 'd6';
  rows: ChildhoodExperienceRow[];
}

function row(roll: string, deprecatedTypes: string[], experience: string, focus: string | null, A: number, B: number, C: number, D: number, E: number, F: number): ChildhoodExperienceRow {
  return { roll, deprecatedTypes, experience, focus, correction: { DEX: A, AGI: B, STR: C, VIT: D, INT: E, SPR: F } };
}

